(()=>{
 const q=s=>document.querySelector(s),root=q('#student-week-calendar');
 let config=null,week=null,generation=0,cleanup=null;
 const node=(tag,value)=>{const e=document.createElement(tag);e.textContent=value;return e};
 async function api(path){const response=await fetch('/api/lessons'+path,{cache:'no-store'});const data=await response.json();if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'Не удалось загрузить расписание.');return data}
 function currentWeek(){const today=WeeklyCalendar.local(new Date(),config.timezone).day;week=WeeklyCalendar.plus(today,-((new Date(today+'T12:00Z').getUTCDay()+6)%7))}
 function details(row){const panel=q('#student-lesson-details');panel.replaceChildren();const close=node('button','Закрыть');close.type='button';close.onclick=()=>panel.hidden=true;const format=value=>new Date(value).toLocaleString('ru-RU',{timeZone:config.timezone,dateStyle:'short',timeStyle:'short'});panel.append(close,node('h3',row.topic||'Математика'),node('p',format(row.starts_at)+' — '+format(row.ends_at)+' · '+config.timezone),node('p',({scheduled:'Запланировано',completed:'Проведено',cancelled:'Отменено'}[row.status])+' · '+row.duration_minutes+' мин'));if(row.meeting_url&&row.status==='scheduled'){const link=node('a','Открыть онлайн-урок →');link.href=row.meeting_url;link.target='_blank';link.rel='noopener noreferrer';panel.append(link)}if(row.status==='completed'){const link=node('a','Домашнее задание и конспект →');link.href='materials.html?lesson_id='+row.id;panel.append(link)}panel.hidden=false;panel.scrollIntoView({block:'nearest'});panel.focus()}
 async function render(){const token=++generation,requested=week;root.setAttribute('aria-busy','true');root.inert=true;q('#student-calendar-status').textContent='Загружаем расписание…';q('#student-week-label').textContent=new Date(week+'T12:00Z').toLocaleDateString('ru-RU',{timeZone:'UTC',day:'numeric',month:'long'})+' — '+new Date(WeeklyCalendar.plus(week,6)+'T12:00Z').toLocaleDateString('ru-RU',{timeZone:'UTC',day:'numeric',month:'long',year:'numeric'});try{let offset=0,total;const rows=[];do{const page=await api('?'+new URLSearchParams({from_date:requested,to_date:WeeklyCalendar.plus(requested,7),overlap:true,limit:100,offset}));if(token!==generation)return;rows.push(...page.items);total=page.total;offset+=100}while(offset<total);if(cleanup)cleanup();q('#student-lesson-details').hidden=true;const range=WeeklyCalendar.studentWindow('lessons',rows,requested,config.timezone);if(!range){cleanup=null;root.replaceChildren();q('#student-calendar-range-label').textContent='';q('#student-calendar-status').textContent='На этой неделе занятий пока нет.';return}const {startMinute,endMinute}=range;const endLabel=String(Math.floor(endMinute/60)).padStart(2,'0')+':'+String(endMinute%60).padStart(2,'0');q('#student-calendar-range-label').textContent='Диапазон: '+String(Math.floor(startMinute/60)).padStart(2,'0')+':'+String(startMinute%60).padStart(2,'0')+'–'+endLabel;cleanup=WeeklyCalendar.render(root,rows,{weekStart:requested,timezone:config.timezone,secondaryZone:'',readOnly:true,startMinute,endMinute,onOpen:details});q('#student-calendar-status').textContent=rows.length?'':'На этой неделе занятий нет.'}catch(e){if(token!==generation)return;if(cleanup)cleanup();cleanup=null;root.replaceChildren();q('#student-calendar-status').textContent=e.message}finally{if(token===generation){root.inert=false;root.setAttribute('aria-busy','false')}}}
 window.stopStudentCalendar=()=>{generation++;if(cleanup)cleanup();cleanup=null;config=null;week=null;root.replaceChildren();q('#student-lesson-details').replaceChildren();q('#student-lesson-details').hidden=true};
 window.loadStudentCalendar=async()=>{window.stopStudentCalendar();const token=generation;try{const settings=await api('/settings');if(token!==generation||settings.role!=='student')return;config=settings;q('#student-calendar-zone').textContent='Ваш часовой пояс: '+config.timezone;currentWeek();await render()}catch(e){if(token===generation)q('#student-calendar-status').textContent=e.message}};
 q('#student-previous-week').onclick=()=>{if(config){week=WeeklyCalendar.plus(week,-7);void render()}};q('#student-next-week').onclick=()=>{if(config){week=WeeklyCalendar.plus(week,7);void render()}};q('#student-current-week').onclick=()=>{if(config){currentWeek();void render()}};q('#student-calendar-refresh').onclick=()=>{if(config)void render()};
})();
